import test from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { Session, SAVE_KEY, loadProfiles } from '../../app/session.mjs';
import { newStudent, readStudent, studentForSave } from '../../recovered/control/student.mjs';
import { queueCertificates } from '../../recovered/control/flow.mjs';
import { timer } from '../../recovered/control/scoring.mjs';
import { createPendingInput, dosTimeSeconds, seedFromTime } from '../../recovered/runtime/runtime.mjs';

// Inert bytes generated by tools/assets/pipeline.py. Never imported as code.
const data = JSON.parse(readFileSync(new URL('../../app/data.json', import.meta.url)));
const exe = readFileSync(new URL('../../assets/original/raw/MarioTea/MARIO/MARIO.EXE.data', import.meta.url));
assert.equal(createHash('sha256').update(exe).digest('hex'),
  '6caed439b64dc3bad8de4f9df53b63ae5712bf3c54b0bbfc00603557e4720f5e');
const at = (offset, hex) => assert.equal(exe.subarray(offset, offset + hex.length / 2).toString('hex'), hex);
const string = offset => exe.subarray(offset, exe.indexOf(0, offset)).toString('ascii');

test('option10 is cached signed KWD threshold, not audio bit 0x10 or quit permission', () => {
  assert.equal(string(0x21bcf), 'KWD');
  assert.equal(exe.readInt16LE(0x1f270 + 0x2892), -1);
  at(0x15045, '833e922800'); // lazy cache initialization when negative
  at(0x1507e, 'a192283b46067c07b80100'); // signed cache >= caller threshold
  at(0x115a7, '9a3c065c11'); // menu Q/Alt-X calls quit directly, no option query
});

test('source raw keyboard has one C pushback byte, no recovered DOS queue capacity', () => {
  at(0x4a41, '803eee3c00');
  at(0x4a52, 'b80007cd21'); // DOS direct input, not an implemented BIOS buffer
  at(0x4de7, 'b40bcd21'); // DOS pending service
  const input = createPendingInput();
  for (let i = 0; i < 1024; ++i) input.enqueue(65 + i % 26);
  for (let i = 0; i < 1024; ++i) assert.equal(input.consume(), 65 + i % 26);
  assert.equal(input.pending(), false); // tests the documented unbounded HOST FIFO only
  input.enqueue(0, 0x48, 0xe0, 0x50, 65);
  assert.equal(input.consume(), 0x148);
  input.flush();
  assert.equal(input.pending(), false);
  assert.throws(() => input.consume(), RangeError);
});

test('low-word changed wait differs from full tick elapsed accounting', () => {
  at(0x192ce, 'a12c4e3b46f674dd'); // compare only BIOS DX with previous low word
  at(0x19343, '8b46f28946fc8b46f08946fe'); // elapsed reader retains DX and CX
  let clock = timer(timer({}, 320, 0), 300, 65535);
  clock = timer(clock, 100, 65536);
  assert.equal(clock.ticks, 1); // low16 rollover must NOT reset full elapsed clock
  clock = timer(clock, 100, 65536);
  assert.equal(clock.ticks, 1);
  clock = timer(clock, 100, 0);
  assert.equal(clock.ticks, -65535); // source has no midnight rollback repair
});

test('DOS calendar conversion accepts explicit offset/DST, seed retains low16', () => {
  assert.equal(string(0x22fc2), 'TZ');
  assert.equal(string(0x22fc5), 'EST');
  assert.equal(string(0x22fc9), 'EDT');
  const calendar = {year: 1980, month: 1, day: 1, hour: 0, minute: 0, second: 0,
    timezoneSeconds: 0, daylightActive: false};
  const utc = dosTimeSeconds(calendar);
  assert.equal(utc, 0x12cea600);
  assert.equal(dosTimeSeconds({...calendar, timezoneSeconds: 18000}), utc + 18000);
  assert.equal(dosTimeSeconds({...calendar, timezoneSeconds: 18000, daylightActive: true}), utc + 14400);
  assert.equal(seedFromTime(utc), 0xa600);
  assert.equal(seedFromTime(utc + 65536), seedFromTime(utc));
  assert.notEqual(seedFromTime(utc + 18000), seedFromTime(utc));
});

test('student save preserves all unowned bytes and three independent certificate arrays', () => {
  const bytes = Uint8Array.from({length: 260}, (_, i) => (i * 37 + 11) & 255);
  const v = new DataView(bytes.buffer);
  bytes[27] = 1; bytes[28] = 1; bytes[29] = 2;
  v.setInt16(19, 75, true); v.setInt16(25, 3, true);
  const before = bytes.slice(), saved = studentForSave(bytes);
  const expected = before.slice(); expected.set([0x1a, 0x53, 0x54, 0x55]); expected[27] = 0;
  assert.deepEqual(saved, expected);
  assert.deepEqual(bytes, before);
  for (const field of ['completed', 'printed', 'pending'])
    assert.deepEqual(readStudent(saved)[field], readStudent(bytes)[field]);
  bytes[28] = 0;
  assert.equal(studentForSave(bytes), null);
  at(0xe296, 'b80401'); at(0xe34c, 'b80401');
});

test('last-used browser pointer remains in existing JSON namespace, not DOS carryon bytes', () => {
  assert.equal(string(0x215f7), 'carryon');
  assert.equal(string(0x21601), '%s'); // no added newline in source carryon save
  at(0xe5bd, 'b81400'); // source fgets bound20, not a 260-byte student
  const bytes = newStudent('ALICE'), other = Array.from(newStudent('BOB'));
  const profiles = {current: 'BOB', students: {alice: Array.from(bytes), BOB: other}};
  const writes = [];
  new Session(data, {bytes, seed: 1}).save({setItem: (...args) => writes.push(args)}, profiles);
  assert.equal(writes.length, 1);
  assert.equal(writes[0][0], SAVE_KEY);
  assert.equal(SAVE_KEY, 'mtt-static-translation.students.v1');
  const stored = JSON.parse(writes[0][1]);
  assert.deepEqual(Object.keys(stored).sort(), ['current', 'students']);
  assert.equal(stored.current, 'alice');
  assert.deepEqual(stored.students.BOB, other);
  assert.equal(stored.students.alice.length, 260);
  assert.deepEqual(loadProfiles({getItem: key => {assert.equal(key, SAVE_KEY); return writes[0][1];}}), stored);
});

test('browser persistence rejects malformed records and exposes write errors without migration', () => {
  for (const record of [[], Array(259).fill(0), Array(260).fill(256), Array(260).fill(0.5)])
    assert.throws(() => loadProfiles({getItem: () => JSON.stringify({current: 'A', students: {A: record}})}));
  const session = new Session(data, {bytes: newStudent('ALICE'), seed: 1});
  const profiles = {current: null, students: {}};
  const denied = new Error('denied');
  assert.throws(() => session.save({setItem: () => {throw denied;}}, profiles), error => error === denied);
  // Existing contract mutates the in-memory object before a failed host write.
  assert.equal(profiles.current, 'ALICE');
  assert.equal(profiles.students.ALICE.length, 260);
});

test('certificate queue never means printed, source document is 60 text rows not CERTIF pixels', () => {
  const profile = {profilePresent: true, completed: [1, 1, 1], printed: [0, 1, 0], pending: [0, 0, 1]};
  const before = structuredClone(profile);
  assert.deepEqual(queueCertificates(profile), [true, false, true]);
  assert.deepEqual(profile, before);
  assert.deepEqual(queueCertificates({...profile, profilePresent: false}), [false, false, true]);
  at(0xa903, 'b85100'); // allocate81 bytes, 80 columns plus NUL
  at(0xa96d, '83fe3c'); at(0xa9ec, '83fe3c'); // allocate/output60 rows
  assert.equal(string(0x20dd2), '%-80.80s\r\n');
  at(0x14a57, 'b8603a'); // FILE object, not framebuffer or image encoder
  at(0x14a67, '9ace370000');
});
